parameters.jsCode:
const apt = $input.first().json.body.appointment;
let cleanPhone = String(apt.phone || '').replace(/[^0-9]/g, '');
if (cleanPhone.length === 10) cleanPhone = '91' + cleanPhone;

// Parse dynamic Google Calendar start & end ISO timestamps (Issue #11)
let dateStr = apt.preferredDate || new Date().toISOString().split('T')[0];
let startHour = 9;
let startMin = 0;
let durationMin = 30;

const timeStr = String(apt.preferredTime || '').toUpperCase();
const timeMatch = timeStr.match(/(\d{1,2}):?(\d{2})?\s*(AM|PM)?/i);
if (timeMatch) {
  let h = parseInt(timeMatch[1], 10);
  let m = timeMatch[2] ? parseInt(timeMatch[2], 10) : 0;
  let meridiem = timeMatch[3];
  if (meridiem === 'PM' && h < 12) h += 12;
  if (meridiem === 'AM' && h === 12) h = 0;
  startHour = h;
  startMin = m;
}

const pad = (n) => String(n).padStart(2, '0');
const startIso = `${dateStr}T${pad(startHour)}:${pad(startMin)}:00+05:30`;

let endHour = startHour;
let endMin = startMin + durationMin;
if (endMin >= 60) {
  endHour += Math.floor(endMin / 60);
  endMin = endMin % 60;
}
const endIso = `${dateStr}T${pad(endHour)}:${pad(endMin)}:00+05:30`;

return {
  Date: apt.preferredDate,
  Time: apt.preferredTime,
  "Patient Name": apt.patientName,
  Contact: cleanPhone,
  Doctor: apt.referringDoctor || 'Self / Walk-in',
  Service: apt.service,
  Status: apt.status || 'New',
  Notes: apt.bookingType === 'home_collection' ? `Home Collection: ${apt.address} (${apt.landmark || 'N/A'}) | Fasting: ${apt.fastingGuidelines}` : `Clinic Walk-in | Fasting: ${apt.fastingGuidelines}`,
  "Payment Status": 'Pending at Centre',
  "Payment Method": 'Cash / UPI',
  Amount: 'To be billed',
  Source: 'Website / WhatsApp',
  "Assigned To": apt.bookingType === 'home_collection' ? 'Phlebotomist' : 'Reception',
  bookingId: apt.id,
  patientName: apt.patientName,
  phone: cleanPhone,
  service: apt.service,
  bookingType: apt.bookingType,
  scheduledDate: apt.preferredDate,
  scheduledTime: apt.preferredTime,
  address: apt.address || 'Clinic Walk-in',
  landmark: apt.landmark || 'N/A',
  googleMapsUrl: apt.googleMapsNavigationUrl || 'N/A',
  fastingInstructions: apt.fastingGuidelines || 'Standard hydration',
  referringDoctor: apt.referringDoctor || 'Self / Walk-in',
  calendarStartIso: startIso,
  calendarEndIso: endIso
};

